create table service_order_number_counters (tenant_id uuid primary key references tenants(id), last_number bigint not null default 0, updated_at timestamptz not null default now());
create table service_orders (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, company_id uuid not null, branch_id uuid not null, order_number bigint not null, customer_id uuid not null, asset_id uuid, status text not null default 'open', title text not null, reported_problem text not null, initial_notes text, opened_at timestamptz not null default now(), created_by_identity_id uuid references identities(id), updated_by_identity_id uuid references identities(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (tenant_id,id), unique (tenant_id,order_number), check (status in ('open','in_progress','completed','canceled')), foreign key (tenant_id,company_id) references companies(tenant_id,id), foreign key (tenant_id,company_id,branch_id) references branches(tenant_id,company_id,id), foreign key (tenant_id,customer_id) references customers(tenant_id,id), foreign key (tenant_id,asset_id) references customer_assets(tenant_id,id));
create index service_orders_list_idx on service_orders(tenant_id,created_at desc); create index service_orders_customer_idx on service_orders(tenant_id,customer_id); create index service_orders_status_idx on service_orders(tenant_id,status);
alter table service_orders enable row level security; alter table service_orders force row level security;
create policy service_orders_tenant_isolation on service_orders using (tenant_id = current_setting('app.tenant_id', true)::uuid) with check (tenant_id = current_setting('app.tenant_id', true)::uuid);
grant select,insert,update on service_order_number_counters,service_orders to vetoros_runtime;
